class Checker:
  def __init__(self, s):
    self.s = s

  def expands_into(self, s2):
    if len(s2) != len(self.s) + 1:
      return False

    # Create frequency maps for both strings
    freq = dict()
    for c in s2:
      if c not in freq:
        freq[c] = 0
      freq[c] += 1

    for c in self.s:
      if c not in freq:
        return False
      freq[c] -= 1
      if freq[c] == 0:
        del freq[c]

    # Should have exactly one character with frequency 1
    return len(freq) == 1 and list(freq.values())[0] == 1

