class RunTests {
  public void runTests() {
    Object[][] tests = {
        // Example 1 
        {
            "tea",
            new Object[][] {
                { "tea", false },
                { "team", true },
                { "seam", false }
            }
        },
        // Example 2 
        {
            "on",
            new Object[][] {
                { "nooo", false },
                { "not", true },
                { "now", true }
            }
        },
        // Additional test cases
        {
            "",
            new Object[][] {
                { "a", true },
                { "", false },
                { "ab", false }
            }
        },
        {
            "xyz",
            new Object[][] {
                { "wxyz", true },
                { "xyzw", true },
                { "xyza", true },
                { "xyz", false }
            }
        }
    };

    for (Object[] test : tests) {
      String s = (String) test[0];
      Object[][] checks = (Object[][]) test[1];
      Checker checker = new Checker(s);
      for (Object[] check : checks) {
        String s2 = (String) check[0];
        boolean want = (boolean) check[1];
        boolean got = checker.expandsInto(s2);
        if (got != want) {
          throw new RuntimeException(String.format(
              "\nChecker(%s).expandsInto(%s): got: %b, want: %b\n",
              s, s2, got, want));
        }
      }
    }
  }
}

public class Solution {
  public static void main(String[] args) {
    new RunTests().runTests();
  }
}
